using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class NurseForwardEyes {
 const string Folder=NurseVisualOptimization.Folder;const string Out=NurseVisualOptimization.Out;
 static Texture2D Read(string p){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(p));return t;}
 static void Save(Color[] p,int n,string path){var t=new Texture2D(n,n,TextureFormat.RGBA32,false,true);t.SetPixels(p);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);}
 public static void Run(){var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab");var renderer=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var mesh=renderer.sharedMesh;var p=mesh.vertices.Select(renderer.transform.TransformPoint).ToArray();var uv=mesh.uv;var tri=mesh.triangles;var eye=Read(Out+"/Moe_NativeEye.png");var nativePacked=Read(Out+"/Moe_NativeEye_RMOE.png");const int n=2048;var packedColors=new Color[512*512];var packedWeights=new float[512*512];var mask=new float[n*n];var artwork=new Color[n*n];
  for(int j=0;j<tri.Length;j+=3){int a=tri[j],b=tri[j+1],c=tri[j+2];if(Mathf.Max(p[a].y,Mathf.Max(p[b].y,p[c].y))<1.62f||Mathf.Min(p[a].y,Mathf.Min(p[b].y,p[c].y))>1.64f)continue;var aa=uv[a]*n;var bb=uv[b]*n;var cc=uv[c]*n;float d=(bb.y-cc.y)*(aa.x-cc.x)+(cc.x-bb.x)*(aa.y-cc.y);if(Mathf.Abs(d)<1e-8f)continue;
   for(int y=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.y,Mathf.Min(bb.y,cc.y))));y<=Mathf.Min(n-1,Mathf.CeilToInt(Mathf.Max(aa.y,Mathf.Max(bb.y,cc.y))));y++)for(int x=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.x,Mathf.Min(bb.x,cc.x))));x<=Mathf.Min(n-1,Mathf.CeilToInt(Mathf.Max(aa.x,Mathf.Max(bb.x,cc.x))));x++){
    float u=((bb.y-cc.y)*(x+.5f-cc.x)+(cc.x-bb.x)*(y+.5f-cc.y))/d,v=((cc.y-aa.y)*(x+.5f-cc.x)+(aa.x-cc.x)*(y+.5f-cc.y))/d,w=1-u-v;if(u<0||v<0||w<0)continue;var position=p[a]*u+p[b]*v+p[c]*w;if(position.z<.025f)continue;float cx=position.x<0?-.0338f:.032f,dx=position.x-cx,dy=position.y-1.628f;float ellipse=dx*dx/(.012f*.012f)+dy*dy/(.006f*.006f);if(ellipse>=1)continue;int i=y*n+x;mask[i]=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.82f,1,ellipse));float irisX=position.x<0?-.030f:.035f;var eyeUV=new Vector2(Mathf.Clamp01(.5f+(position.x-irisX)/.02164291f),Mathf.Clamp01(.5f+dy/.02164291f));artwork[i]=eye.GetPixelBilinear(eyeUV.x,eyeUV.y);int pi=(y/4)*512+x/4;float pm=mask[i]/16f;packedColors[pi]+=nativePacked.GetPixelBilinear(eyeUV.x,eyeUV.y)*pm;packedWeights[pi]+=pm;
   }
  }
  foreach(string tier in new[]{"","_Feral"}){string path=Folder+"/Atlas_Albedo"+tier+".png";var colors=Read(path).GetPixels();for(int i=0;i<colors.Length;i++)if(mask[i]>0){float alpha=colors[i].a;colors[i]=Color.Lerp(colors[i],artwork[i],mask[i]);colors[i].a=alpha;}Save(colors,n,path);}
  foreach(string tier in new[]{"Normal","Feral","Special"}){string path=Folder+"/Atlas_RMOE_"+tier+".png";var colors=Read(path).GetPixels();for(int i=0;i<colors.Length;i++)if(packedWeights[i]>0){float alpha=colors[i].a;colors[i]=Color.Lerp(colors[i],packedColors[i]/packedWeights[i],Mathf.Clamp01(packedWeights[i]));colors[i].a=alpha;}Save(colors,512,path);}
  string normalPath=Folder+"/Atlas_Normal.png";var normals=Read(normalPath).GetPixels();for(int i=0;i<normals.Length;i++)if(mask[i]>0){var v=new Vector3(normals[i].r*2-1,normals[i].g*2-1,normals[i].b*2-1);v=Vector3.Lerp(v,Vector3.forward,mask[i]).normalized;normals[i]=new Color(v.x*.5f+.5f,v.y*.5f+.5f,v.z*.5f+.5f,1);}Save(normals,n,normalPath);
  File.WriteAllText(Out+"/forward-eyes.txt","Actual extracted Moe normal-eye albedo and RMOE replace the generated human-blue eye. Fixed scleral apertures (-.0338,1.628) and (.032,1.628) metres. Independently registered iris centres (-.030,1.628) and (.035,1.628) metres; artwork shifts inside stationary eye openings, rather than moving the full eye patch. Albedo iris registration corrected on body and shared eye UV surfaces. Texels="+mask.Count(x=>x>0)+".\n");
 }
}
